"""Generate the public extension page, privacy notice and setup guide."""
from pathlib import Path
from html import escape
import re
from social_meta import social_meta, PUBLIC_URL

def document(title,body,name):
    return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(title)+' · Goofish Br</title>'+social_meta(title+' · Goofish Br',PUBLIC_URL+name)+'<link rel="icon" href="./assets/jv-mascot.png"><link rel="stylesheet" href="./shop.css?v=15"><link rel="stylesheet" href="./jv.css?v=15"><style>pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f5e9;padding:20px;border-radius:16px}code{overflow-wrap:anywhere}li{margin:10px 0}</style></head><body><header><div class="wrap header-row"><a class="brand" href="./"><img class="brand-mascot" src="./assets/jv-mascot.png" alt=""><b>Goofish <em>Br</em></b></a><a class="button" href="./">Ver produtos</a></div></header><main class="wrap legal-content">'+body+'</main></body></html>'

def markdown(text):
    output=[];code=False;paragraph=[]
    def flush():
        if paragraph: output.append('<p>'+'<br>'.join(paragraph)+'</p>');paragraph.clear()
    for line in text.splitlines():
        if line.startswith('```'):
            flush();output.append('</code></pre>' if code else '<pre><code>');code=not code;continue
        if code: output.append(escape(line)+'\n');continue
        if not line.strip():flush();continue
        m=re.match(r'^(#{1,3}) (.*)',line)
        if m:flush();n=len(m[1]);output.append(f'<h{n}>'+escape(m[2])+f'</h{n}>');continue
        value=escape(line)
        value=re.sub(r'(https://[^\s<>]+)',r'<a href="\1" target="_blank" rel="noopener">\1</a>',value)
        value=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',value)
        paragraph.append(value)
    flush();return ''.join(output)

def build_extension_page(public):
    root=Path(__file__).parent
    body="""<section class="extension-hero"><div><h1>Seu próximo achado começa aqui.</h1><p>Explore os produtos do catálogo Goofish Br sem entrar em uma conta chinesa. Pesquise, compare e guarde os seus favoritos.</p><a class="button black" href="./downloads/goofish-br-extensao-1.2.0.zip" download>Baixar extensão para Chrome</a></div><img src="./assets/mascot-search.png" alt="Mascote Goofish Br com uma lupa"></section><div class="extension-facts"><span><strong>4.720 anúncios</strong> no catálogo</span><span><strong>Sem conta chinesa</strong> para pesquisar o catálogo</span><span><strong>Yuan + real</strong> lado a lado</span></div><div class="extension-banners"><section class="extension-banner dark"><div><h2>Do achado<br>ao seu agente.</h2><p>Escolha o produto e abra o link no agente. Sem ficar copiando o mesmo endereço de um lado para o outro.</p></div><img src="./assets/mascot-wave.png" alt="Mascote acenando" loading="lazy"></section><section class="extension-banner"><div><h2>Guarde o que<br>vale a pena.</h2><p>Separe seus favoritos por pasta e compare preços com calma. Seus próximos achados ficam por perto.</p></div><img src="./assets/mascot-heart.png" alt="Mascote segurando um coração" loading="lazy"></section></div><h2 class="extension-heading">Tudo no seu ritmo.</h2><div class="extension-features"><article class="extension-feature"><h3>Busca dentro da extensão</h3><p>Pesquise os anúncios salvos do Goofish com filtros de categoria, preço, cor e condição citadas no texto.</p></article><article class="extension-feature"><h3>Fotos e informações juntas</h3><p>Abra a galeria, confira os dados disponíveis do vendedor e veja o preço em yuan e a estimativa em reais.</p></article><article class="extension-feature"><h3>Links para os agentes</h3><p>Abra o anúncio na Hubbuy, Superbuy, CSSBuy, Fansbuy ou USFans. Aceitação e custos finais dependem do agente.</p></article><article class="extension-feature"><h3>Sua coleção organizada</h3><p>Pastas, fornecedores favoritos, backup e importação. Os dados locais continuam disponíveis entre visitas.</p></article><article class="extension-feature"><h3>Cotação e comparação</h3><p>Use sua cotação ou consulte a disponível no dia. Compare propostas e frete até o armazém informados pelos agentes.</p></article><article class="extension-feature"><h3>Compartilhe os achados</h3><p>Com sua nuvem configurada, compartilhe pastas, sincronize a coleção e acompanhe mudanças confirmadas de preço.</p></article></div><section id="instalar" class="extension-install"><div><h2>Pronto para explorar?</h2><p>A versão atual é a <strong>1.2.0</strong>. A Goofish Br ainda não está na Chrome Web Store; por enquanto, a instalação é manual.</p><p><a class="button black" href="./downloads/goofish-br-extensao-1.2.0.zip" download>Baixar Goofish Br</a></p></div><ol><li>Baixe e extraia o arquivo em uma pasta permanente.</li><li>Abra <code>chrome://extensions</code> e ative <strong>Modo do desenvolvedor</strong>.</li><li>Clique em <strong>Carregar sem compactação</strong> e selecione a pasta com <code>manifest.json</code>.</li><li>Fixe a extensão e clique em <strong>Explorar produtos</strong>.</li></ol></section><section class="extension-online"><h2>O catálogo é livre para explorar.</h2><p>A pesquisa dos 4.720 anúncios funciona sem login e sem servidor no seu PC. O catálogo contém capturas anteriores: preços, traduções e disponibilidade devem ser conferidos na origem.</p><p>A busca ao vivo de novos anúncios é uma função separada e depende de uma fonte própria configurada. A API privada da EVO não faz parte desta extensão. Sincronização, compartilhamento e alertas precisam da sua conta Cloudflare; alertas reais também precisam de uma fonte acessível de preços.</p><div class="actions"><a class="button" href="./cloudflare.html">Configurar recursos online</a><a class="button" href="./downloads/goofish-br-cloudflare-1.2.0.zip" download>Baixar projeto da API</a></div></section><footer class="extension-footer"><span>Projeto independente. Sem vínculo oficial com Goofish/Xianyu ou EVO Society.</span><a href="./privacidade-extensao.html">Privacidade</a><a href="mailto:jv.busca@gmail.com">Contato</a></footer>"""
    (public/'extensao.html').write_text(document('Extensão',body,'extensao.html').replace('<main class="wrap legal-content">','<main class="wrap extension-landing">').replace('</head>','<link rel="stylesheet" href="./extension-landing.css?v=12"></head>'),encoding='utf-8')
    (public/'cloudflare.html').write_text(document('Ativar recursos online',markdown((root/'cloudflare/LEIA-ME.md').read_text(encoding='utf-8')),'cloudflare.html'),encoding='utf-8')
    privacy=(root/'extension-shop/privacy.html').read_text(encoding='utf-8')
    body=re.search(r'<section>(.*?)</section>',privacy,re.S).group(1)
    (public/'privacidade-extensao.html').write_text(document('Privacidade da extensão',body,'privacidade-extensao.html'),encoding='utf-8')
